import { expect, test } from "bun:test";

function average(a: number, b: number): number {
	return Math.floor((a + b) / 2);
}

function randomInt(min: number, max: number): number {
	return min + Math.floor(Math.random() * (max - min + 1));
}

test("average property", () => {
	for (let i = 0; i < 1000; i++) {
		const a = randomInt(-100, 100);
		const b = randomInt(-100, 100);
		expect(average(a, b)).toBe(Math.floor((a + b) / 2));
	}
});

example.content:
const result = average(a, b);
expect(result).toBeGreaterThanOrEqual(Math.min(a, b));
expect(result).toBeLessThanOrEqual(Math.max(a, b));
expect(average(b, a)).toBe(result);

